/* GENERATED from codex-data.json — the full 78-card tarot deck (22 Major + 56 Minor).
   Real Blue Room codex data. Each: name, tag, keywords[], meaning (upright), reversed, group, rank, suit, element. */
window.TAROT_DECK = [{"name": "The Fool","tag": "0 · Major Arcana","keywords": ["new beginnings","innocence","spontaneity","leap of faith","freedom"],"meaning": "The Fool represents new beginnings, innocence, and a leap into the unknown. It depicts a free spirit stepping toward a cliff's edge, trusting in the journey rather than the destination. The card signals openness to experience, spontaneity, and a willingness to take risks without over-planning. It marks the start of the Fool's Journey through the rest of the Major Arcana.","reversed": "Reversed, The Fool warns of recklessness, naivety, or poor judgment. It can indicate being unprepared for risk, acting without thinking through consequences, or being held back by fear of taking a needed leap.","group": "major","rank": "0","suit": null,"element": "Major Arcana"},{"name": "The Magician","tag": "I · Major Arcana","keywords": ["manifestation","willpower","resourcefulness","skill","action"],"meaning": "The Magician stands for manifestation, willpower, and the resourceful use of one's skills and tools to turn ideas into reality. Traditionally shown with the four suit symbols on a table and one hand raised to the sky, one pointing to earth, he channels higher inspiration into concrete action. The card signals confidence, focus, and the ability to make things happen. It represents the point where potential becomes purposeful action.","reversed": "Reversed, The Magician suggests manipulation, trickery, or untapped talent. It can point to poor planning, deceit, or someone using their skills for selfish or dishonest ends.","group": "major","rank": "I","suit": null,"element": "Major Arcana"},{"name": "The High Priestess","tag": "II · Major Arcana","keywords": ["intuition","mystery","the subconscious","inner knowledge","stillness"],"meaning": "The High Priestess represents intuition, the subconscious mind, and hidden or as-yet-unrevealed knowledge. Seated between two pillars, veiled from ordinary sight, she guards mysteries that must be accessed through inner reflection rather than logic. The card calls for patience, listening to inner guidance, and trusting what is felt over what is proven. It signals secrets, dreams, and knowledge not yet ready to be spoken.","reversed": "Reversed, she suggests disconnection from intuition, secrets coming to light, or information being withheld or misused. It can point to confusion, repressed feelings, or ignoring one's inner voice.","group": "major","rank": "II","suit": null,"element": "Major Arcana"},{"name": "The Empress","tag": "III · Major Arcana","keywords": ["abundance","nurturing","fertility","nature","creativity"],"meaning": "The Empress embodies abundance, nurturing, fertility, and the creative force of nature. She is often shown enthroned amid lush growth, symbolizing motherhood, sensuality, and material and creative flourishing. The card signals a period of growth, comfort, and connection to the natural world or one's own creative and nurturing instincts. It can also relate literally to pregnancy, birth, or a growing project.","reversed": "Reversed, The Empress can indicate creative block, neglect (of self or others), smothering or codependent nurturing, or issues around fertility, body image, or overindulgence.","group": "major","rank": "III","suit": null,"element": "Major Arcana"},{"name": "The Emperor","tag": "IV · Major Arcana","keywords": ["authority","structure","stability","leadership","control"],"meaning": "The Emperor represents authority, structure, and stable, rational leadership. Seated on a stone throne, he embodies order, discipline, and the establishment of rules and boundaries that provide security. The card signals a father-figure energy: protection through structure, strategic thinking, and the will to build and defend something lasting. It favors logic and long-term planning over impulsiveness.","reversed": "Reversed, The Emperor points to domination, rigidity, or abuse of power, or conversely a lack of discipline and structure. It can indicate an overbearing authority figure or a loss of control.","group": "major","rank": "IV","suit": null,"element": "Major Arcana"},{"name": "The Hierophant","tag": "V · Major Arcana","keywords": ["tradition","institutions","conformity","spiritual guidance","education"],"meaning": "The Hierophant represents tradition, established institutions, and conventional belief systems such as religion, education, or formal codes of conduct. Often depicted as a religious or spiritual teacher flanked by two acolytes, he stands for learning from recognized authorities and communal structures. The card signals conformity, seeking guidance through proven systems, and rites of passage such as marriage or formal education.","reversed": "Reversed, The Hierophant suggests rebellion against convention, unconventional beliefs, or challenging outdated institutions. It can also indicate restriction from rigid dogma or personal, unorthodox spirituality.","group": "major","rank": "V","suit": null,"element": "Major Arcana"},{"name": "The Lovers","tag": "VI · Major Arcana","keywords": ["love","union","choice","harmony","relationships"],"meaning": "The Lovers represents love, deep connection, and harmony between partners, as well as significant choices, especially those involving values and relationships. Traditionally depicted as a man and woman before an angel, it echoes themes of duality and union. The card signals attraction, partnership, and moments demanding a decision that aligns with one's core values.","reversed": "Reversed, The Lovers can indicate disharmony, imbalance in a relationship, or a difficult choice made poorly or avoided. It may point to infidelity, misalignment of values, or self-love issues.","group": "major","rank": "VI","suit": null,"element": "Major Arcana"},{"name": "The Chariot","tag": "VII · Major Arcana","keywords": ["willpower","determination","victory","self-discipline","drive"],"meaning": "The Chariot represents willpower, determination, and victory achieved through focus and self-discipline. It shows a figure driving two opposing forces (often sphinxes) forward in the same direction through sheer force of will. The card signals overcoming obstacles, maintaining control amid conflicting forces, and pushing decisively toward a goal.","reversed": "Reversed, The Chariot suggests lack of direction, loss of control, or being pulled in opposing directions. It can indicate aggression, self-doubt, or a failure to assert the will needed to move forward.","group": "major","rank": "VII","suit": null,"element": "Major Arcana"},{"name": "Strength","tag": "VIII · Major Arcana","keywords": ["courage","inner strength","patience","compassion","self-control"],"meaning": "Strength represents inner fortitude, courage, and the mastery of raw impulse through patience and compassion rather than brute force. It is typically shown as a woman gently calming a lion with her bare hands, symbolizing the taming of instinct through gentleness. The card signals quiet resilience, emotional control, and facing challenges with a calm, steady heart.","reversed": "Reversed, Strength points to self-doubt, weakness, or a loss of inner control, sometimes expressed as raw aggression or as being overwhelmed by fear and insecurity.","group": "major","rank": "VIII","suit": null,"element": "Major Arcana"},{"name": "The Hermit","tag": "IX · Major Arcana","keywords": ["introspection","solitude","inner guidance","withdrawal","wisdom"],"meaning": "The Hermit represents introspection, solitude, and the search for inner truth. Depicted as an old figure holding a lantern that lights the way alone on a mountain, he symbolizes withdrawal from the world to seek wisdom and self-understanding. The card signals a need for reflection, stepping back from external distractions, and following one's own inner light rather than the crowd.","reversed": "Reversed, The Hermit suggests isolation, loneliness, or withdrawal taken too far, as well as refusing needed guidance or avoiding necessary introspection.","group": "major","rank": "IX","suit": null,"element": "Major Arcana"},{"name": "Wheel of Fortune","tag": "X · Major Arcana","keywords": ["cycles","fate","change","turning points","luck"],"meaning": "The Wheel of Fortune represents cycles, fate, and the turning points of life that lie beyond personal control. It depicts a great wheel, often with symbolic figures and alchemical or astrological symbols, illustrating the constant rise and fall of fortune. The card signals change, unexpected turns, and the reminder that both good and bad fortune are temporary phases in an ongoing cycle.","reversed": "Reversed, the Wheel suggests bad luck, resistance to change, or feeling like a victim of circumstance. It can also point to a cycle repeating because its lesson has not yet been learned.","group": "major","rank": "X","suit": null,"element": "Major Arcana"},{"name": "Justice","tag": "XI · Major Arcana","keywords": ["fairness","truth","law","cause and effect","accountability"],"meaning": "Justice represents fairness, truth, and the law of cause and effect. Shown seated with a sword and scales, the figure weighs actions and their consequences impartially. The card signals accountability, the need for honesty and balance, and matters of legal or ethical decision-making where truth ultimately prevails.","reversed": "Reversed, Justice points to unfairness, dishonesty, or avoidance of accountability. It can indicate a biased outcome, legal complications, or consequences one is trying to escape.","group": "major","rank": "XI","suit": null,"element": "Major Arcana"},{"name": "The Hanged Man","tag": "XII · Major Arcana","keywords": ["surrender","new perspective","letting go","suspension","sacrifice"],"meaning": "The Hanged Man represents surrender, suspension, and gaining a new perspective by pausing rather than pushing forward. Depicted hanging upside down from one foot, calm rather than distressed, he symbolizes voluntary sacrifice or a change in viewpoint that brings insight. The card signals a need to let go of control, accept a period of waiting, and see a situation from a different angle.","reversed": "Reversed, The Hanged Man suggests stalling, resistance to necessary sacrifice, or feeling stuck without gaining the intended insight. It can indicate martyrdom or delaying a decision out of fear.","group": "major","rank": "XII","suit": null,"element": "Major Arcana"},{"name": "Death","tag": "XIII · Major Arcana","keywords": ["endings","transformation","transition","letting go","rebirth"],"meaning": "Death represents endings, transformation, and the transition from one state of being to another. It rarely refers to literal death, instead symbolizing the necessary conclusion of a chapter, relationship, habit, or identity to make way for renewal. The card signals profound change, release of what no longer serves, and the natural cycle of ending and rebirth.","reversed": "Reversed, Death suggests resistance to change, being stuck in a stagnant situation, or a fear of letting go that delays necessary transformation.","group": "major","rank": "XIII","suit": null,"element": "Major Arcana"},{"name": "Temperance","tag": "XIV · Major Arcana","keywords": ["balance","moderation","patience","harmony","integration"],"meaning": "Temperance represents balance, moderation, and the harmonious blending of opposites. Often shown as an angel pouring liquid between two cups, it symbolizes patience, careful integration, and finding the middle path. The card signals a call for calm, measured action, healing, and combining differing elements (ideas, people, or emotions) into a workable whole.","reversed": "Reversed, Temperance points to imbalance, excess, or impatience. It can indicate overindulgence, discord between conflicting needs, or a lack of long-term perspective.","group": "major","rank": "XIV","suit": null,"element": "Major Arcana"},{"name": "The Devil","tag": "XV · Major Arcana","keywords": ["bondage","materialism","addiction","temptation","shadow self"],"meaning": "The Devil represents bondage, materialism, and unhealthy attachment, often to habits, desires, or relationships that limit freedom. It depicts a horned figure with two chained figures, though the chains are loose enough to be removed, suggesting the bondage is largely self-imposed. The card signals addiction, obsession, and confronting one's shadow self or destructive patterns.","reversed": "Reversed, The Devil suggests breaking free from limiting patterns, releasing an addiction, or reclaiming personal power. It can also indicate ongoing denial about a harmful attachment.","group": "major","rank": "XV","suit": null,"element": "Major Arcana"},{"name": "The Tower","tag": "XVI · Major Arcana","keywords": ["sudden upheaval","destruction","revelation","chaos","awakening"],"meaning": "The Tower represents sudden, disruptive upheaval that destroys false structures and forces revelation. It depicts a tower struck by lightning, its inhabitants falling from a height, symbolizing the collapse of illusions, beliefs, or situations built on unstable foundations. The card signals a shocking event or realization that, while painful, clears the way for necessary truth and rebuilding.","reversed": "Reversed, The Tower suggests disaster narrowly avoided, or an inevitable collapse being delayed or resisted, prolonging instability. It can also point to internal upheaval not yet outwardly expressed.","group": "major","rank": "XVI","suit": null,"element": "Major Arcana"},{"name": "The Star","tag": "XVII · Major Arcana","keywords": ["hope","inspiration","renewal","faith","healing"],"meaning": "The Star represents hope, inspiration, and renewal following a period of hardship. It shows a figure pouring water under a starlit sky, symbolizing healing, spiritual replenishment, and faith in the future. The card signals optimism, calm after the storm, and a renewed sense of purpose and connection to something greater.","reversed": "Reversed, The Star suggests despair, loss of faith, or feeling disconnected from hope and inspiration. It can indicate self-doubt or a period of discouragement following disappointment.","group": "major","rank": "XVII","suit": null,"element": "Major Arcana"},{"name": "The Moon","tag": "XVIII · Major Arcana","keywords": ["illusion","fear","the unconscious","uncertainty","intuition"],"meaning": "The Moon represents illusion, fear, and the murky realm of the unconscious and dreams. It depicts a moonlit path between two towers, guarded by a wolf and dog, with a crayfish emerging from water, symbolizing hidden fears and instincts rising to the surface. The card signals uncertainty, confusion, and a need to trust intuition when clear answers are not available.","reversed": "Reversed, The Moon suggests the release of fear, the resolving of confusion, or repressed emotions and hidden truths coming to light. It can also indicate ongoing self-deception or anxiety.","group": "major","rank": "XVIII","suit": null,"element": "Major Arcana"},{"name": "The Sun","tag": "XIX · Major Arcana","keywords": ["joy","success","vitality","clarity","positivity"],"meaning": "The Sun represents joy, success, and vitality. It depicts a radiant sun shining over a child (often riding a horse), symbolizing clarity, warmth, and unguarded happiness. The card signals genuine positivity, achievement, good health, and a phase of life illuminated by confidence and truth.","reversed": "Reversed, The Sun can indicate temporary sadness, a delay in success, or an overly inflated ego. It often points to a dimming, rather than disappearance, of the card's natural optimism.","group": "major","rank": "XIX","suit": null,"element": "Major Arcana"},{"name": "Judgement","tag": "XX · Major Arcana","keywords": ["reckoning","rebirth","inner calling","absolution","evaluation"],"meaning": "Judgement represents reckoning, rebirth, and answering an inner call to a higher purpose. It depicts figures rising from graves at the sound of an angel's trumpet, symbolizing awakening, self-evaluation, and absolution. The card signals a pivotal moment of reflection on past actions, culminating in renewal, forgiveness, or a decisive turning point.","reversed": "Reversed, Judgement suggests self-doubt, harsh self-criticism, or failing to heed an inner calling. It can indicate avoidance of necessary reflection or difficulty forgiving oneself or others.","group": "major","rank": "XX","suit": null,"element": "Major Arcana"},{"name": "The World","tag": "XXI · Major Arcana","keywords": ["completion","fulfillment","wholeness","accomplishment","integration"],"meaning": "The World represents completion, fulfillment, and the successful integration of a long journey's lessons. It depicts a dancing figure encircled by a laurel wreath, surrounded by the four fixed-sign symbols, signaling wholeness and accomplishment. The card marks the end of the Fool's Journey through the Major Arcana: a cycle brought to satisfying closure, ready to begin anew at a higher level.","reversed": "Reversed, The World suggests incompletion, delays, or a sense of something left unresolved. It can indicate a need for closure or difficulty moving on to the next stage of life.","group": "major","rank": "XXI","suit": null,"element": "Major Arcana"},{"name": "Ace of Wands","tag": "Ace · Wands · Fire","keywords": ["inspiration","new venture","creative spark","potential","initiative"],"meaning": "The Ace of Wands represents the pure potential of Fire: a fresh spark of inspiration, passion, and creative drive not yet given shape. Traditionally shown as a hand emerging from a cloud, offering a sprouting wand toward the sky with a distant castle beyond. Uniting the Ace's seed-potential with the suit's element of energy and ambition, the card signals the birth of a new venture, idea, or pursuit charged with enthusiasm. It favors seizing an opening, following a sudden creative urge, or committing to the first step of something bold.","reversed": "Reversed, the Ace of Wands suggests delays, a lack of motivation, or inspiration that has not yet found its direction. It can indicate a creative block, a false start, or enthusiasm that dissipates before a plan takes form.","group": "minor","rank": "Ace","suit": "Wands","element": "Fire"},{"name": "Two of Wands","tag": "Two · Wands · Fire","keywords": ["planning","future vision","personal power","discovery","decision"],"meaning": "The Two of Wands stands for planning, personal power, and the pull between comfort and the wider world. Traditionally shown as a figure standing on a castle battlement, holding a globe and gazing out over distant land, one wand held in hand and another fixed to the wall. Joining the number two's choice with the drive of Wands, the card signals a moment of deliberate strategy after the Ace's initial spark, weighing ambition against the security already built. It favors mapping out a bold next move, considering options for growth, and preparing to act on a larger vision.","reversed": "Reversed, the Two of Wands can indicate indecision, fear of the unknown, or plans that stall before they begin. It may point to playing it too safe, a lack of clear direction, or ambitions left unexamined.","group": "minor","rank": "Two","suit": "Wands","element": "Fire"},{"name": "Three of Wands","tag": "Three · Wands · Fire","keywords": ["expansion","foresight","progress","anticipation","trade"],"meaning": "The Three of Wands represents expansion, foresight, and the early results of a plan already set in motion. Traditionally shown as a figure standing at a cliff's edge, back to the viewer, watching ships sail toward the horizon with three wands planted firmly beside him. Fusing the number three's growth with the ambition of Wands, the card signals a venture moving outward and gaining momentum, its outcome still awaited but its direction already clear. It favors patience while opportunities travel toward fruition, and confidence in plans already committed to.","reversed": "Reversed, the Three of Wands suggests delays, obstacles to expansion, or a lack of foresight in planning ahead. It can indicate progress stalling unexpectedly, or overconfidence about a venture whose results have not yet arrived.","group": "minor","rank": "Three","suit": "Wands","element": "Fire"},{"name": "Four of Wands","tag": "Four · Wands · Fire","keywords": ["celebration","homecoming","stability","harmony","milestone"],"meaning": "The Four of Wands embodies celebration, homecoming, and a stable foundation reached after sustained effort. Traditionally shown as four wands forming a garlanded canopy, with figures dancing and celebrating beneath it and a castle standing in the distance. Combining the number four's stability with the vibrant energy of Wands, the card signals a milestone worth marking: a wedding, a homecoming, or the successful completion of a stage of work. It favors gathering with others to mark an achievement and enjoying a foundation now firmly set.","reversed": "Reversed, the Four of Wands can indicate a delayed celebration, instability at home, or a milestone reached without the joy expected. It may point to transition, a canceled gathering, or difficulty feeling settled.","group": "minor","rank": "Four","suit": "Wands","element": "Fire"},{"name": "Five of Wands","tag": "Five · Wands · Fire","keywords": ["conflict","competition","rivalry","friction","struggle"],"meaning": "The Five of Wands represents conflict, competition, and the friction that arises when several strong wills clash. Traditionally shown as five young men crossing staves in a chaotic mock battle, each seemingly fighting a different fight. Fusing the number five's discord with the driving energy of Wands, the card signals rivalry, disagreement, or a scramble for attention and advantage. It favors channeling competitive energy constructively, and recognizing when a struggle is more noise than genuine threat.","reversed": "Reversed, the Five of Wands suggests conflict avoidance, an unresolved rivalry, or tension finally easing after a struggle. It can indicate infighting resolving into cooperation, or friction suppressed rather than addressed.","group": "minor","rank": "Five","suit": "Wands","element": "Fire"},{"name": "Six of Wands","tag": "Six · Wands · Fire","keywords": ["victory","recognition","success","confidence","triumph"],"meaning": "The Six of Wands speaks to victory, public recognition, and the confidence earned by hard-won success. Traditionally shown as a rider on horseback wearing a laurel wreath, holding a wand also crowned with laurel, greeted by a supportive crowd. Joining the number six's harmony with the ambition of Wands, the card signals triumph after struggle, and the resolution of the Five's conflict into acclaim. It favors accepting recognition earned through effort, and standing confidently in a moment of success.","reversed": "Reversed, the Six of Wands can indicate delayed recognition, a fall from favor, or private doubt behind a public victory. It may point to an achievement going unacknowledged, or success won at the cost of others' goodwill.","group": "minor","rank": "Six","suit": "Wands","element": "Fire"},{"name": "Seven of Wands","tag": "Seven · Wands · Fire","keywords": ["defense","perseverance","standing ground","challenge","resilience"],"meaning": "The Seven of Wands represents defense, perseverance, and holding one's position against challenge. Traditionally shown as a figure standing on higher ground, wielding a wand to fend off six wands raised against him from below. Combining the number seven's assessment with the assertive drive of Wands, the card signals a test of resolve, often arriving after success has drawn competitors or critics. It favors standing firm on ground already earned, defending a position under pressure, and staying committed despite opposition.","reversed": "Reversed, the Seven of Wands suggests feeling overwhelmed, giving up a defended position, or exhaustion from constant struggle. It can indicate self-doubt under pressure, or being unprepared for the challenges that success invites.","group": "minor","rank": "Seven","suit": "Wands","element": "Fire"},{"name": "Eight of Wands","tag": "Eight · Wands · Fire","keywords": ["swift movement","momentum","travel","acceleration","rapid change"],"meaning": "The Eight of Wands stands for swift movement, momentum, and events accelerating toward resolution. Traditionally shown as eight wands flying in formation through a clear sky over open land, with no figures pictured to slow their flight. Fusing the number eight's forward motion with the restless energy of Wands, the card signals rapid developments, quick decisions, and communication or travel arriving without delay. It favors acting decisively while momentum is high, and staying alert as circumstances shift quickly.","reversed": "Reversed, the Eight of Wands suggests delays, frustration, or plans that lose momentum after moving quickly. It can indicate miscommunication, travel setbacks, or events slowing just as they seemed ready to resolve.","group": "minor","rank": "Eight","suit": "Wands","element": "Fire"},{"name": "Nine of Wands","tag": "Nine · Wands · Fire","keywords": ["resilience","last stand","boundaries","vigilance","persistence"],"meaning": "The Nine of Wands represents resilience, vigilance, and the persistence needed for one last effort. Traditionally shown as a bandaged, weary figure leaning on a wand, standing guard before a fence of eight more wands. Joining the number nine's near-completion with the enduring energy of Wands, the card signals a defender worn by prior battles but still holding a boundary, close to the end of a long struggle. It favors drawing on inner reserves for a final push, and staying guarded without giving up entirely.","reversed": "Reversed, the Nine of Wands can indicate exhaustion, burnout, or an unwillingness to compromise after too much struggle. It may point to defensiveness that has become rigid, or resilience finally giving way.","group": "minor","rank": "Nine","suit": "Wands","element": "Fire"},{"name": "Ten of Wands","tag": "Ten · Wands · Fire","keywords": ["burden","overload","responsibility","struggle","completion"],"meaning": "The Ten of Wands embodies burden, overload, and the weight of responsibilities carried alone. Traditionally shown as a figure bent under the weight of ten wands, struggling toward a distant home with vision nearly blocked by the load. Fusing the number ten's culmination with the driving effort of Wands, the card signals success achieved through sheer determination but now strained by too much taken on at once. It favors recognizing when a load has grown unsustainable, and considering what can be set down or shared.","reversed": "Reversed, the Ten of Wands suggests releasing a burden, delegating responsibility, or collapse under weight carried too long. It can indicate finally putting something down, or burnout from refusing to ask for help.","group": "minor","rank": "Ten","suit": "Wands","element": "Fire"},{"name": "Page of Wands","tag": "Page · Wands · Fire","keywords": ["curiosity","enthusiasm","exploration","new venture","messenger"],"meaning": "The Page of Wands represents curiosity, enthusiasm, and the eagerness of a beginner discovering a new passion. Traditionally shown as a young figure standing in an open desert landscape, studying a sprouting wand with evident wonder, pyramids visible in the distance. Combining the youth and messages of the Page with the fiery drive of Wands, the card signals a fresh interest, a bold idea, or news of a new venture worth exploring. It favors following curiosity, taking an early exploratory step, and approaching a new pursuit with open enthusiasm.","reversed": "Reversed, the Page of Wands suggests scattered enthusiasm, hesitation to commit, or excitement that fades before it is acted on. It can indicate impulsive plans without follow-through, or news of a venture delayed.","group": "minor","rank": "Page","suit": "Wands","element": "Fire"},{"name": "Knight of Wands","tag": "Knight · Wands · Fire","keywords": ["action","adventure","impulsiveness","passion","haste"],"meaning": "The Knight of Wands speaks to bold action, adventure, and passion pursued at full speed. Traditionally shown as an armored rider on a rearing horse, plumed and decorated with salamanders, charging forward with a wand in hand. Joining the Knight's momentum with the restless energy of Wands, the card signals confident, fast-moving pursuit of a goal, often with little patience for delay. It favors decisive action and a willingness to take risks, tempered by an awareness that haste can outrun planning.","reversed": "Reversed, the Knight of Wands suggests recklessness, impulsiveness, or plans abandoned as quickly as they were begun. It can indicate frustration from delays, or energy scattered across too many pursuits at once.","group": "minor","rank": "Knight","suit": "Wands","element": "Fire"},{"name": "Queen of Wands","tag": "Queen · Wands · Fire","keywords": ["confidence","warmth","independence","vitality","charisma"],"meaning": "The Queen of Wands represents confidence, warmth, and independence expressed with magnetic energy. Traditionally shown seated on a throne carved with lions and sunflowers, a black cat at her feet, holding a wand and sunflower with an assured, direct gaze. Fusing the Queen's inward mastery with the vibrant drive of Wands, the card signals a self-assured presence that draws others in through vitality rather than force. It favors leading with warmth and determination, and trusting one's own charisma and judgment.","reversed": "Reversed, the Queen of Wands can indicate insecurity, jealousy, or confidence turned demanding and controlling. It may point to warmth withheld, self-doubt beneath a bold exterior, or energy spent seeking approval.","group": "minor","rank": "Queen","suit": "Wands","element": "Fire"},{"name": "King of Wands","tag": "King · Wands · Fire","keywords": ["leadership","vision","boldness","authority","entrepreneurship"],"meaning": "The King of Wands stands for visionary leadership, boldness, and command of ambition put to purposeful use. Traditionally shown seated on a throne decorated with lions and salamanders, holding a flowering wand with a steady, commanding presence. Joining the King's outward mastery with the driving element of Wands, the card signals a leader who inspires action, takes calculated risks, and turns vision into enterprise. It favors decisive leadership, entrepreneurial confidence, and setting an ambitious direction for others to follow.","reversed": "Reversed, the King of Wands suggests impulsiveness, arrogance, or authority used to dominate rather than inspire. It can indicate a leader overreaching, ruthless ambition, or vision pursued without regard for others.","group": "minor","rank": "King","suit": "Wands","element": "Fire"},{"name": "Ace of Cups","tag": "Ace · Cups · Water","keywords": ["new love","emotional beginning","openness","compassion","intuition"],"meaning": "The Ace of Cups represents the pure potential of the heart: new love, emotional beginnings, and an outpouring of compassion. Traditionally shown as a hand emerging from a cloud, offering an overflowing chalice from which five streams spill while a dove descends bearing a wafer, it depicts grace entering the emotional life. Fusing the Ace's seed-like potential with the Water of Cups, the card signals an open heart, a fresh wellspring of feeling, and the start of a relationship, friendship, or creative or spiritual outpouring. It favors receptivity, vulnerability, and letting compassion flow freely rather than holding it back.","reversed": "Reversed, the Ace of Cups suggests a blocked or repressed heart, an emotional opportunity left untaken, or love that has not yet found its outlet. It can indicate self-doubt in matters of feeling, emptiness where fullness was hoped for, or emotions kept guarded rather than shared.","group": "minor","rank": "Ace","suit": "Cups","element": "Water"},{"name": "Two of Cups","tag": "Two · Cups · Water","keywords": ["partnership","mutual attraction","connection","harmony","union"],"meaning": "The Two of Cups stands for partnership, mutual attraction, and the harmony of two people meeting as equals. Traditionally shown as a man and woman facing each other, each raising a cup in exchange beneath a winged lion's head or caduceus, it depicts a bond formed through balanced give and take. Joining the number two's theme of pairing and choice with the emotional current of Cups, the card signals romance, friendship, or reconciliation grounded in mutual respect rather than grand declaration. It favors budding connection, healed rifts, and relationships that feel evenly matched.","reversed": "Reversed, the Two of Cups can indicate a relationship out of balance, miscommunication between two people, or a connection that has cooled or broken. It may point to one-sidedness, a falling-out, or tension between partners who once matched well.","group": "minor","rank": "Two","suit": "Cups","element": "Water"},{"name": "Three of Cups","tag": "Three · Cups · Water","keywords": ["celebration","friendship","community","joy","reunion"],"meaning": "The Three of Cups represents celebration, friendship, and the shared joy of community. It is traditionally shown as three women raising their cups in a toast and dancing together amid a harvest of fruit and flowers. Uniting the number three's creative growth with the emotional current of Cups, the card signals reunions, gatherings, and happiness that multiplies when it is shared. It favors the support of close friends, collaboration, and milestones marked in good company.","reversed": "Reversed, the Three of Cups can indicate isolation, a falling-out among friends, or celebration soured by gossip or overindulgence. It may point to feeling left out of a group, a strained social circle, or joy dimmed by too much of a good thing.","group": "minor","rank": "Three","suit": "Cups","element": "Water"},{"name": "Four of Cups","tag": "Four · Cups · Water","keywords": ["apathy","contemplation","discontent","missed opportunity","withdrawal"],"meaning": "The Four of Cups embodies apathy, contemplation, and a discontent that has turned inward. Traditionally shown as a young figure seated beneath a tree with arms crossed, staring at three cups on the ground while a hand offers a fourth from a cloud unnoticed, it depicts a mind too absorbed in its own feelings to see what is being offered. Combining the number four's stillness and stability with the emotional inwardness of Cups, the card signals boredom, emotional withdrawal, or a reevaluation that has settled into restless dissatisfaction. It can also relate to taking a needed pause, though one that risks curdling into indifference if it lasts too long.","reversed": "Reversed, the Four of Cups suggests a return of interest after apathy, a new opportunity finally recognized, or a shift out of stagnation. It may point to renewed motivation, reengagement with others, or waking up to something previously overlooked.","group": "minor","rank": "Four","suit": "Cups","element": "Water"},{"name": "Five of Cups","tag": "Five · Cups · Water","keywords": ["grief","loss","regret","mourning","overlooked comfort"],"meaning": "The Five of Cups represents grief, loss, and regret over what has spilled and cannot be recovered. Traditionally shown as a cloaked figure standing before three overturned, emptied cups, back turned to two cups still standing upright behind, it depicts mourning so consuming that remaining comfort goes unseen. Fusing the number five's conflict and loss with the emotional depth of Cups, the card signals sorrow, disappointment, or dwelling on what went wrong. It favors eventually turning around to notice what still remains, without denying the weight of what was lost.","reversed": "Reversed, the Five of Cups can indicate acceptance, moving on from grief, or finally recognizing what still remains after a loss. It may point to forgiveness, recovery from disappointment, or the first steps of emotional healing.","group": "minor","rank": "Five","suit": "Cups","element": "Water"},{"name": "Six of Cups","tag": "Six · Cups · Water","keywords": ["nostalgia","childhood memory","reunion","innocence","warmth"],"meaning": "The Six of Cups stands for nostalgia, childhood memory, and the warmth of simple, innocent giving. Traditionally shown as two children in a garden exchanging flower-filled cups, it depicts a scene of comfort and familiarity untouched by complication. Joining the number six's harmony and recovery with the emotional register of Cups, the card signals fond memories, a reunion with someone from the past, or a return to a simpler, more sincere way of relating. It can also relate to gestures of kindness that carry an unguarded, childlike generosity.","reversed": "Reversed, the Six of Cups suggests being stuck in the past, idealized nostalgia, or a reunion that revives old wounds along with old warmth. It may point to reluctance to move forward, or relationships and habits kept alive out of comfort rather than present need.","group": "minor","rank": "Six","suit": "Cups","element": "Water"},{"name": "Seven of Cups","tag": "Seven · Cups · Water","keywords": ["choices","illusion","fantasy","wishful thinking","daydreaming"],"meaning": "The Seven of Cups represents choices, fantasy, and the difficulty of telling illusion from substance. Traditionally shown as a figure facing seven cups afloat in clouds, each holding a different vision such as a castle, jewels, a laurel wreath, or a shrouded figure, it depicts a mind confronted with tempting but insubstantial options. Combining the number seven's assessment with the emotional imagination of Cups, the card signals daydreaming, wishful thinking, and the need to weigh appealing possibilities against what is actually real or attainable. It favors clear-eyed discernment over being pulled in every direction by desire.","reversed": "Reversed, the Seven of Cups suggests clarity after confusion, a choice finally made, or illusions giving way to a more realistic view. It can indicate cutting through fantasy, focus replacing scattered wishing, or facing consequences that were previously avoided.","group": "minor","rank": "Seven","suit": "Cups","element": "Water"},{"name": "Eight of Cups","tag": "Eight · Cups · Water","keywords": ["walking away","seeking meaning","letting go","disillusionment","a deeper search"],"meaning": "The Eight of Cups stands for walking away from what no longer satisfies in search of something deeper. Traditionally shown as a lone figure departing at night, leaving eight stacked cups behind and heading toward distant mountains beneath a waning moon, it depicts a deliberate departure rather than an impulsive one. Fusing the number eight's mastery and forward movement with the emotional weight of Cups, the card signals leaving behind a relationship, situation, or achievement that has stopped fulfilling its purpose. It favors trusting that abandoning surface comfort can serve a more meaningful pursuit.","reversed": "Reversed, the Eight of Cups can indicate reluctance to leave a situation that has already run its course, or a return to something that was previously left behind. It may point to fear of the unknown, stagnation disguised as loyalty, or aimless drifting without a clear direction.","group": "minor","rank": "Eight","suit": "Cups","element": "Water"},{"name": "Nine of Cups","tag": "Nine · Cups · Water","keywords": ["satisfaction","contentment","wish fulfilled","comfort","emotional abundance"],"meaning": "The Nine of Cups represents satisfaction, contentment, and a wish granted. Traditionally shown as a figure seated with arms crossed before an arc of nine cups displayed like trophies, wearing a pleased and settled expression, it depicts comfort earned and enjoyed. Joining the number nine's near-completion and intensity with the emotional fullness of Cups, the card signals a sense of having what one wants, pleasure, and gratification, often called the wish card for its association with desires coming true. It favors genuine contentment, though it can tip toward complacency or self-satisfaction if unchecked.","reversed": "Reversed, the Nine of Cups suggests unfulfilled wishes, a hollow or overindulgent form of pleasure, or contentment that is more performed than felt. It can indicate dissatisfaction despite outward success, or a need to reassess what genuinely brings fulfillment.","group": "minor","rank": "Nine","suit": "Cups","element": "Water"},{"name": "Ten of Cups","tag": "Ten · Cups · Water","keywords": ["emotional fulfillment","family harmony","happy home","lasting joy","togetherness"],"meaning": "The Ten of Cups stands for emotional fulfillment, family harmony, and lasting domestic happiness. Traditionally shown as a rainbow of ten cups arcing over a couple with arms raised and children dancing nearby, a home visible in the distance, it depicts a settled, shared joy rather than a solitary triumph. Combining the number ten's completion with the emotional depth of Cups, the card signals a happy household, deep contentment in relationships, and emotional goals reached together with others. It favors gratitude for the life already built, particularly the bonds of family and close community.","reversed": "Reversed, the Ten of Cups suggests disharmony at home, a family or relationship falling short of its ideal, or happiness that looks complete from outside but feels hollow within. It may point to unresolved conflict, misaligned values among loved ones, or a fractured sense of belonging.","group": "minor","rank": "Ten","suit": "Cups","element": "Water"},{"name": "Page of Cups","tag": "Page · Cups · Water","keywords": ["emotional curiosity","creative message","intuitive discovery","a dreamer","new feeling"],"meaning": "The Page of Cups represents emotional curiosity, a creative or intuitive message, and the wide-eyed beginning of feeling something new. Traditionally shown as a young figure at the shore holding a cup from which a fish playfully emerges, it depicts surprise and imagination breaking into ordinary awareness. Combining the Page's youthful, message-bearing role with the emotional intuition of Cups, the card signals an emotional or creative discovery, an invitation to daydream, or news arriving that touches the heart. It favors sensitivity, openness to inspiration, and approaching feelings with a beginner's wonder rather than caution.","reversed": "Reversed, the Page of Cups can indicate emotional immaturity, a message poorly received, or creative blocks born of insecurity. It may point to moodiness, escapism, or difficulty separating genuine intuition from wishful imagination.","group": "minor","rank": "Page","suit": "Cups","element": "Water"},{"name": "Knight of Cups","tag": "Knight · Cups · Water","keywords": ["romantic pursuit","invitation","idealism","following the heart","a graceful offer"],"meaning": "The Knight of Cups stands for romantic pursuit, an invitation offered with sincerity, and following the heart's ideal. Traditionally shown as a knight in winged helmet and boots riding at a measured, graceful pace, holding a cup out before him, it depicts a quest driven by feeling rather than force. Joining the Knight's active pursuit with the emotional current of Cups, the card signals a romantic gesture, an artistic or emotional proposal, or movement toward something desired at an unhurried, deliberate pace. It favors charm, imagination, and pursuing what is loved rather than what is merely useful.","reversed": "Reversed, the Knight of Cups suggests unrealistic romantic ideals, a gesture that turns out to be empty, or moodiness masked as sensitivity. It can indicate withdrawal from a pursuit, disappointment when fantasy meets reality, or jealousy stirred by unmet emotional expectations.","group": "minor","rank": "Knight","suit": "Cups","element": "Water"},{"name": "Queen of Cups","tag": "Queen · Cups · Water","keywords": ["emotional intuition","compassion","empathy","inner depth","nurturing wisdom"],"meaning": "The Queen of Cups represents deep emotional intuition, compassion, and a nurturing wisdom turned inward before it is offered outward. Traditionally shown seated at the water's edge, gazing into an ornate, closed cup shaped like a small chapel, she depicts feeling held with quiet self-containment rather than displayed openly. Combining the Queen's inner mastery with the emotional depth of Cups, the card signals empathy, sensitivity to others' unspoken needs, and comfort drawn from one's own emotional world. It favors caring for others without losing one's own emotional footing.","reversed": "Reversed, the Queen of Cups can indicate emotional overwhelm, codependency, or compassion given until little is left for oneself. It may point to moodiness, insecurity dressed as intuition, or difficulty setting boundaries around one's own feelings.","group": "minor","rank": "Queen","suit": "Cups","element": "Water"},{"name": "King of Cups","tag": "King · Cups · Water","keywords": ["emotional mastery","calm authority","diplomacy","balanced feeling","steady heart"],"meaning": "The King of Cups stands for emotional mastery expressed outwardly, calm authority, and the diplomatic balancing of heart and head. Traditionally shown seated on a throne that rises from a turbulent sea, holding a cup and scepter steady despite the surrounding waves, he depicts composure maintained amid emotional turbulence. Joining the King's outward command with the emotional depth of Cups, the card signals maturity in handling feelings, both one's own and others', and leadership guided by empathy rather than impulse. It favors measured counsel, generosity, and steadiness in relationships that require patience.","reversed": "Reversed, the King of Cups suggests emotional volatility hidden beneath a calm surface, manipulation through charm, or moods that leak out despite an appearance of control. It can indicate coldness, emotional withdrawal, or advice given from a place of unresolved feeling rather than genuine balance.","group": "minor","rank": "King","suit": "Cups","element": "Water"},{"name": "Ace of Swords","tag": "Ace · Swords · Air","keywords": ["clarity","breakthrough","truth","new idea","mental power"],"meaning": "The Ace of Swords represents clarity, breakthrough, and the sudden cutting-through of confusion by a sharp new idea. Traditionally shown as a hand emerging from a cloud, gripping an upright sword crowned with a laurel wreath, it offers the raw seed of the suit's element in its purest form. Fusing the Ace's pure potential with the intellectual charge of Swords and Air, the card signals a moment of mental clarity, an unclouded truth, or the first flash of an idea capable of cutting through confusion. It favors decisive thinking, honest communication, and the courage to name a hard truth plainly.","reversed": "Reversed, the Ace of Swords suggests confusion, a clouded or misused idea, or a truth twisted into miscommunication. It can point to mental fog, a plan cut short, or clarity gained only after unnecessary conflict.","group": "minor","rank": "Ace","suit": "Swords","element": "Air"},{"name": "Two of Swords","tag": "Two · Swords · Air","keywords": ["stalemate","indecision","avoidance","balance","blocked truth"],"meaning": "The Two of Swords speaks to stalemate, indecision, and a deliberate avoidance of a difficult choice. Traditionally pictured as a blindfolded woman seated before the sea, arms crossed and holding two swords in careful balance, it shows a mind holding two opposing truths at bay rather than facing either. Uniting the number two's theme of choice with the mental domain of Swords, the card signals a standoff between the head and the heart, or a truth deliberately not looked at. It favors acknowledging the tension honestly rather than prolonging the impasse.","reversed": "Reversed, the Two of Swords indicates the blindfold coming off, a stalemate finally broken, or a decision made after too much delay. It can also point to information overload, indecision tipping into confusion, or a choice made carelessly to escape the discomfort of waiting.","group": "minor","rank": "Two","suit": "Swords","element": "Air"},{"name": "Three of Swords","tag": "Three · Swords · Air","keywords": ["heartbreak","sorrow","betrayal","grief","painful truth"],"meaning": "The Three of Swords represents heartbreak, sorrow, and the pain of a truth that wounds. It is traditionally shown as a red heart pierced by three swords against a grey, rain-streaked sky, an image with little ambiguity in its meaning. Combining the number three's growth with the cutting edge of Swords and Air, the card signals emotional pain delivered through words, betrayal, or an unwelcome realization rather than through circumstance alone. It can also relate to grief that, however sharp, clears the way for honest healing.","reversed": "Reversed, the Three of Swords suggests the beginning of recovery from heartbreak, or old grief resurfacing to be released. It can indicate forgiveness, a slow easing of pain, or sorrow suppressed rather than faced.","group": "minor","rank": "Three","suit": "Swords","element": "Air"},{"name": "Four of Swords","tag": "Four · Swords · Air","keywords": ["rest","recovery","contemplation","retreat","stillness"],"meaning": "The Four of Swords stands for rest, recovery, and a deliberate withdrawal for the sake of healing. Traditionally shown as a knight's effigy lying still on a tomb, hands folded in prayer, with three swords mounted on the wall above and one lying beneath, it depicts pause rather than defeat. Fusing the number four's stability with the mental restlessness of Swords, the card signals a needed retreat from conflict or overthinking, a chance for the mind to rest before returning to action. It favors quiet convalescence, meditation, or simply stepping back from strain.","reversed": "Reversed, the Four of Swords warns of restlessness that resists needed rest, or a forced return to activity before recovery is complete. It can indicate burnout from refusing to pause, or stagnation from remaining in retreat far longer than necessary.","group": "minor","rank": "Four","suit": "Swords","element": "Air"},{"name": "Five of Swords","tag": "Five · Swords · Air","keywords": ["conflict","hollow victory","discord","betrayal","win at a cost"],"meaning": "The Five of Swords represents conflict, discord, and a victory won at too high a cost. It is traditionally depicted as a smirking figure gathering up swords while two others walk away in defeat beneath a windswept, turbulent sky. Joining the number five's conflict and loss with the combative edge of Swords, the card signals arguments where winning damages trust, or a triumph that leaves the field empty of allies. It can also point to a dispute better walked away from than won.","reversed": "Reversed, the Five of Swords suggests the aftermath of conflict: reconciliation, a truce, or the willingness to let go of a fight not worth winning. It can also indicate lingering resentment, an unresolved grudge, or conflict avoided out of exhaustion rather than resolved.","group": "minor","rank": "Five","suit": "Swords","element": "Air"},{"name": "Six of Swords","tag": "Six · Swords · Air","keywords": ["transition","moving on","recovery","calmer waters","leaving behind"],"meaning": "The Six of Swords embodies transition, moving on, and the passage from difficulty toward calmer circumstances. Traditionally shown as a ferryman guiding a woman and child across still water in a small boat, six swords standing upright behind them, it depicts a journey away from turbulence rather than its resolution in place. Uniting the number six's harmony and recovery with the mental clarity of Swords and Air, the card signals a deliberate move forward, often leaving behind an old situation or way of thinking that no longer serves. It favors gradual healing found through distance and forward motion.","reversed": "Reversed, the Six of Swords indicates resistance to necessary change, or being unable to leave a difficult situation behind. It can point to a stalled transition, unresolved baggage carried into the next chapter, or a return to old troubles.","group": "minor","rank": "Six","suit": "Swords","element": "Air"},{"name": "Seven of Swords","tag": "Seven · Swords · Air","keywords": ["strategy","deception","stealth","going it alone","evasion"],"meaning": "The Seven of Swords represents strategy, stealth, and a solitary or evasive approach to a difficult situation. It is traditionally shown as a figure creeping away from a camp with five swords gathered in his arms, leaving two behind, glancing back as he goes. Fusing the number seven's assessment with the cunning of Swords, the card signals calculated action taken alone, whether shrewd self-reliance or outright deception. It can also point to withholding information, cutting corners, or a plan that only partly succeeds.","reversed": "Reversed, the Seven of Swords suggests a deception coming to light, a guilty conscience, or getting caught in a scheme. It can also indicate returning what was taken, coming clean, or abandoning a strategy of secrecy in favor of honesty.","group": "minor","rank": "Seven","suit": "Swords","element": "Air"},{"name": "Eight of Swords","tag": "Eight · Swords · Air","keywords": ["restriction","self-imposed limits","entrapment","fear","mental bondage"],"meaning": "The Eight of Swords speaks to restriction, entrapment, and a sense of being bound that is largely self-imposed. Traditionally pictured as a blindfolded, loosely bound woman standing hemmed in by eight swords, the arrangement leaves an evident path free, though she cannot see it. Combining the number eight's mastery and movement with the mental domain of Swords, the card signals a mind trapped by fear, self-doubt, or a story it keeps repeating rather than by any real barrier. It favors recognizing that the way out exists, even when panic obscures it.","reversed": "Reversed, the Eight of Swords indicates release from a self-imposed trap, a new sense of freedom, or finally seeing a way out that was there all along. It can also point to continued self-victimization or a fear so entrenched that the blindfold stays on by choice.","group": "minor","rank": "Eight","suit": "Swords","element": "Air"},{"name": "Nine of Swords","tag": "Nine · Swords · Air","keywords": ["anxiety","worry","nightmares","mental anguish","despair"],"meaning": "The Nine of Swords represents anxiety, worry, and mental anguish that intensifies in the dark, private hours. It is traditionally shown as a figure sitting upright in bed, head in hands, nine swords mounted on the wall behind, the quilt below marked with roses and zodiac symbols. Joining the number nine's intensity with the racing mind of Swords and Air, the card signals sleepless dread, catastrophic thinking, or a fear that looms larger than the facts support. It can also relate to guilt or grief replayed in the mind until it feels inescapable.","reversed": "Reversed, the Nine of Swords suggests worry beginning to ease, or facing a fear that, once examined in daylight, proves smaller than imagined. It can also indicate anxiety suppressed rather than confronted, or a spiral of dread returning after a brief respite.","group": "minor","rank": "Nine","suit": "Swords","element": "Air"},{"name": "Ten of Swords","tag": "Ten · Swords · Air","keywords": ["painful ending","betrayal","rock bottom","release","the worst is over"],"meaning": "The Ten of Swords stands for a painful ending, betrayal, and reaching a definitive rock bottom. Traditionally shown as a figure lying face down with ten swords piercing the back beneath a dark sky, it depicts an ending too complete to be denied, though the horizon shows the first light of dawn breaking. Fusing the number ten's culmination with the harsh clarity of Swords, the card signals a conclusion reached through betrayal, defeat, or exhaustion of options rather than through choice. It favors the recognition that, however severe, there is nowhere further to fall, and the only direction left is up.","reversed": "Reversed, the Ten of Swords suggests recovery beginning after a painful ending, or the slow resistance to accepting that something is truly over. It can indicate a gradual rebuilding, or the fear of a similar collapse recurring.","group": "minor","rank": "Ten","suit": "Swords","element": "Air"},{"name": "Page of Swords","tag": "Page · Swords · Air","keywords": ["curiosity","vigilance","new ideas","alertness","communication"],"meaning": "The Page of Swords represents curiosity, vigilance, and an eager, unformed engagement with new ideas and information. Traditionally shown as a youthful figure standing on a windswept hilltop, sword raised and gaze fixed as if startled into alertness, it depicts a mind quick to notice and question. Carrying the Page's beginner energy into the domain of Swords and Air, the card signals messages, new studies, or a restless curiosity eager to investigate and communicate what it finds. It favors watchfulness, honest questions, and a willingness to learn before assuming.","reversed": "Reversed, the Page of Swords suggests gossip, scattered thinking, or acting on incomplete information. It can point to miscommunication, all talk and no follow-through, or curiosity turned careless and intrusive.","group": "minor","rank": "Page","suit": "Swords","element": "Air"},{"name": "Knight of Swords","tag": "Knight · Swords · Air","keywords": ["swift action","ambition","assertiveness","impulsiveness","momentum"],"meaning": "The Knight of Swords embodies swift action, ambition, and a forceful drive toward a goal. It is traditionally depicted charging on horseback at full gallop, sword raised, riding directly into a gusting wind and storm clouds. Carrying the Knight's momentum into the mental domain of Swords and Air, the card signals decisive, fast-moving pursuit of an idea or objective, argued or acted on without hesitation. It can also indicate impulsiveness, or ambition that outpaces patience and consideration for others.","reversed": "Reversed, the Knight of Swords warns of recklessness, aggression, or action taken without adequate thought. It can indicate a plan derailed by haste, an argument pushed too far, or ambition scattered across too many directions at once.","group": "minor","rank": "Knight","suit": "Swords","element": "Air"},{"name": "Queen of Swords","tag": "Queen · Swords · Air","keywords": ["clear perception","independence","direct communication","discernment","unclouded judgment"],"meaning": "The Queen of Swords represents clear perception, independence, and direct, unsentimental communication. Traditionally shown enthroned with an upright sword in hand, one palm raised outward, clouds and a lone bird behind her, she embodies a mind sharpened by experience rather than softened by it. Turning the Queen's inward mastery toward the domain of Swords and Air, the card signals discernment earned through hardship, honest speech, and boundaries drawn without apology. It favors seeing a situation plainly and saying what is true, even when it is unwelcome.","reversed": "Reversed, the Queen of Swords suggests coldness, harsh judgment, or communication turned cutting rather than clarifying. It can also indicate bitterness from past pain, isolation, or discernment clouded by suspicion.","group": "minor","rank": "Queen","suit": "Swords","element": "Air"},{"name": "King of Swords","tag": "King · Swords · Air","keywords": ["intellectual authority","logic","truth","fair judgment","clear thinking"],"meaning": "The King of Swords speaks to intellectual authority, logic, and judgment grounded in clear, impartial thinking. Traditionally shown seated on a throne carved with butterflies and cherubs, an upright sword in hand and a stern, composed expression, he embodies command of the mind exercised in service of truth. Directing the King's outward mastery into the domain of Swords and Air, the card signals leadership through reason, structured argument, and decisions made on evidence rather than emotion. It favors fairness, clear communication, and authority earned through demonstrated expertise.","reversed": "Reversed, the King of Swords suggests judgment turned cold, manipulative, or overly rigid, or abuse of intellectual authority to dominate rather than clarify. It can also indicate poor judgment, cruelty disguised as honesty, or logic used to justify a predetermined conclusion.","group": "minor","rank": "King","suit": "Swords","element": "Air"},{"name": "Ace of Pentacles","tag": "Ace · Pentacles · Earth","keywords": ["new opportunity","prosperity","manifestation","security","seed"],"meaning": "The Ace of Pentacles represents new opportunity, material prosperity, and the seed of a stable, tangible beginning. Traditionally shown as a hand emerging from a cloud offering a single large coin above a flourishing garden, with a path leading through an archway toward distant mountains. Carrying the Ace's pure potential into the Earth element, the card signals a fresh start in work, finances, health, or home — a concrete opportunity worth pursuing. It favors practical first steps, such as a job offer, a new investment, or the founding of something meant to last.","reversed": "Reversed, the Ace of Pentacles suggests a missed opportunity, a delayed start, or instability in finances or work. It can indicate poor planning, a lost chance for security, or an offer that turns out to be less solid than it first appeared.","group": "minor","rank": "Ace","suit": "Pentacles","element": "Earth"},{"name": "Two of Pentacles","tag": "Two · Pentacles · Earth","keywords": ["balance","juggling priorities","adaptability","flexibility","resourcefulness"],"meaning": "The Two of Pentacles stands for balance, juggling multiple priorities, and adaptability amid shifting material demands. Traditionally shown as a figure dancing while juggling two coins joined by an infinity-shaped ribbon, with ships riding uneven waves in the background. Bringing the Two's choice and duality into the Earth element, the card signals the ongoing work of managing time, money, or competing responsibilities without dropping either. It favors flexibility, good humor under pressure, and staying light on one's feet through change.","reversed": "Reversed, the Two of Pentacles points to disorganization, overcommitment, or an inability to keep priorities in balance. It can indicate dropped responsibilities, financial disarray, or feeling overwhelmed by too many demands at once.","group": "minor","rank": "Two","suit": "Pentacles","element": "Earth"},{"name": "Three of Pentacles","tag": "Three · Pentacles · Earth","keywords": ["collaboration","craftsmanship","skill","teamwork","recognition"],"meaning": "The Three of Pentacles represents skilled collaboration, craftsmanship, and work recognized by others. Traditionally shown as a stonemason carving a cathedral archway while a monk and an architect look on, consulting plans together. Uniting the Three's creative growth with the practical labor of Pentacles, the card signals building something of quality through teamwork, expertise, and shared purpose. It favors apprenticeship, constructive feedback, and early recognition for competent, careful work.","reversed": "Reversed, the Three of Pentacles suggests poor teamwork, mediocre workmanship, or a lack of recognition for effort put in. It can indicate misaligned collaborators, cut corners, or a project stalled by disorganization.","group": "minor","rank": "Three","suit": "Pentacles","element": "Earth"},{"name": "Four of Pentacles","tag": "Four · Pentacles · Earth","keywords": ["security","control","possessiveness","conservation","holding on"],"meaning": "The Four of Pentacles embodies material security taken to the point of control, possessiveness, and a tight grip on what one has. Traditionally shown as a figure clutching a coin to the chest, with one coin underfoot, one balanced on the head, and one held close, guarding wealth on every side. Carrying the Four's stability into the Earth element, the card signals the impulse to conserve, save, and defend resources against loss. It can also point to caution around spending or a reluctance to share, rooted in a fear of scarcity.","reversed": "Reversed, the Four of Pentacles suggests loosening one's grip, either through generosity or through an unwanted loss of control over money or possessions. It can indicate overspending, financial insecurity, or letting go of a possessive, guarded stance.","group": "minor","rank": "Four","suit": "Pentacles","element": "Earth"},{"name": "Five of Pentacles","tag": "Five · Pentacles · Earth","keywords": ["hardship","financial loss","exclusion","worry","struggle"],"meaning": "The Five of Pentacles represents material hardship, financial loss, and the feeling of being left out in the cold. Traditionally shown as two figures, one injured and one poorly dressed, trudging through snow past a lit stained-glass church window. Fusing the Five's conflict and loss with the practical domain of Pentacles, the card signals a period of scarcity, worry over money or health, or feeling excluded from support that is near but unseen. It favors seeking help that may already be available, even when it does not feel that way.","reversed": "Reversed, the Five of Pentacles can indicate the end of a hard financial stretch, recovery, or finding help and community after a period of struggle. It may also point to a lingering scarcity mindset even after the crisis itself has passed.","group": "minor","rank": "Five","suit": "Pentacles","element": "Earth"},{"name": "Six of Pentacles","tag": "Six · Pentacles · Earth","keywords": ["generosity","charity","giving and receiving","balance","support"],"meaning": "The Six of Pentacles speaks to generosity, charity, and the balanced exchange of giving and receiving. Traditionally shown as a wealthy figure distributing coins to two kneeling beggars while holding a set of scales. Bringing the Six's harmony and recovery into the Earth element, the card signals material or practical support changing hands, whether as charity, a loan, an allowance, or mutual aid. It favors fairness in giving, gratitude in receiving, and awareness of the power dynamic between the two.","reversed": "Reversed, the Six of Pentacles suggests an imbalance in giving and receiving, such as strings-attached generosity, one-sided debt, or charity withheld. It can indicate financial dependence, favoritism, or a gift given to gain control.","group": "minor","rank": "Six","suit": "Pentacles","element": "Earth"},{"name": "Seven of Pentacles","tag": "Seven · Pentacles · Earth","keywords": ["patience","assessment","investment","growth","evaluation"],"meaning": "The Seven of Pentacles represents patience, assessment, and the evaluation of an investment of time, money, or labor. Traditionally shown as a farmer leaning on a hoe, pausing to study a vine heavy with pentacles before deciding whether to keep tending it or bring in the harvest. Uniting the Seven's stock-taking with the practical growth of Pentacles, the card signals a pause to weigh progress made so far against effort still required. It favors patience, long-term thinking, and honest appraisal of whether a project is worth continued investment.","reversed": "Reversed, the Seven of Pentacles suggests impatience, wasted effort, or a poor return on time and resources invested. It can indicate giving up too soon, or continuing to invest in something that has already stopped paying off.","group": "minor","rank": "Seven","suit": "Pentacles","element": "Earth"},{"name": "Eight of Pentacles","tag": "Eight · Pentacles · Earth","keywords": ["diligence","craftsmanship","skill-building","focus","apprenticeship"],"meaning": "The Eight of Pentacles stands for diligence, craftsmanship, and the steady mastery of a skill through repetition. Traditionally shown as a craftsman at a workbench, carving pentacle after pentacle with careful concentration while finished pieces hang nearby. Fusing the Eight's mastery and momentum with the practical labor of Pentacles, the card signals dedicated work, apprenticeship, and pride taken in the quality of one's output. It favors focus, routine practice, and building expertise one careful task at a time.","reversed": "Reversed, the Eight of Pentacles suggests sloppy or rushed work, a lack of focus, or skills left undeveloped. It can indicate perfectionism that stalls progress, or effort applied without real craft or care behind it.","group": "minor","rank": "Eight","suit": "Pentacles","element": "Earth"},{"name": "Nine of Pentacles","tag": "Nine · Pentacles · Earth","keywords": ["self-sufficiency","abundance","independence","refinement","reward"],"meaning": "The Nine of Pentacles represents self-sufficiency, material abundance, and the refined comfort earned through one's own independent effort. Traditionally shown as a well-dressed figure standing alone in a lush, pentacle-laden vineyard with a hooded falcon at hand. Uniting the Nine's near-completion with the Earth element's material focus, the card signals a hard-won reward: financial independence, a comfortable home, or satisfaction taken in solitude rather than shared achievement. It favors discipline that has paid off and confidence earned through self-reliance.","reversed": "Reversed, the Nine of Pentacles suggests overwork, financial setback, or dependence on others for security one would rather provide alone. It can indicate isolation that has curdled into loneliness, or comfort maintained at an unsustainable cost.","group": "minor","rank": "Nine","suit": "Pentacles","element": "Earth"},{"name": "Ten of Pentacles","tag": "Ten · Pentacles · Earth","keywords": ["legacy","family","wealth","tradition","long-term security"],"meaning": "The Ten of Pentacles embodies legacy, generational wealth, and long-term material security built over a lifetime. Traditionally shown as an elderly figure with family and dogs gathered beneath an archway bearing the family arms, ten coins arranged around the scene. Bringing the Ten's completion to the Earth element's practical concerns, the card signals inheritance, established tradition, and stability that extends beyond a single person to a family or community. It can also relate to estate planning, home ownership, or the culmination of long-term financial effort.","reversed": "Reversed, the Ten of Pentacles suggests family disputes over money, a legacy squandered, or instability in long-term plans. It can indicate broken tradition, financial setbacks affecting the whole family, or a foundation less secure than it appears.","group": "minor","rank": "Ten","suit": "Pentacles","element": "Earth"},{"name": "Page of Pentacles","tag": "Page · Pentacles · Earth","keywords": ["study","new opportunity","practical curiosity","ambition","beginner's focus"],"meaning": "The Page of Pentacles represents a student of the material world: practical curiosity, a new opportunity, and the focused ambition of a beginner. Traditionally shown as a young figure standing in an open field, studying a single pentacle held up before them. Carrying the Page's youth and messages into the Earth element, the card signals the start of a course of study, a new job, or a fledgling plan approached with careful attention. It favors diligence over flash, and a grounded, teachable attitude toward a new material goal.","reversed": "Reversed, the Page of Pentacles suggests procrastination, a lack of follow-through, or an opportunity approached carelessly. It can indicate unrealistic plans, poor financial habits just forming, or news of a delay in practical matters.","group": "minor","rank": "Page","suit": "Pentacles","element": "Earth"},{"name": "Knight of Pentacles","tag": "Knight · Pentacles · Earth","keywords": ["diligence","steadiness","patience","routine","methodical progress"],"meaning": "The Knight of Pentacles speaks to diligence, steadiness, and methodical progress toward a practical goal. Traditionally shown mounted on a heavy, unmoving black horse in a plowed field, holding a pentacle and surveying the work ahead rather than rushing into it. Fusing the Knight's pursuit with the Earth element's patience, the card signals slow, reliable effort: routine, responsibility, and a refusal to be hurried off a sound plan. It favors persistence over speed and can point to someone, or an approach, that is dependable to the point of being cautious.","reversed": "Reversed, the Knight of Pentacles suggests stagnation, stubbornness, or being so cautious that progress stalls entirely. It can indicate boredom with routine, laziness, or a rigid unwillingness to adapt a practical plan.","group": "minor","rank": "Knight","suit": "Pentacles","element": "Earth"},{"name": "Queen of Pentacles","tag": "Queen · Pentacles · Earth","keywords": ["nurture","practicality","abundance","groundedness","domestic care"],"meaning": "The Queen of Pentacles represents nurture expressed through practical care, material abundance, and a deep groundedness in the physical world. Traditionally shown enthroned in a garden, holding a pentacle in her lap with a rabbit at her feet, comfortable amid nature's abundance. Turning the Queen's inner mastery of the suit inward, the card signals a nurturing competence: managing a home, finances, or the wellbeing of others with warmth and steady hands. It favors self-care, hospitality, and a comfortable, generous relationship with the material world.","reversed": "Reversed, the Queen of Pentacles suggests neglect of self or home, financial insecurity, or nurturing that has become smothering or codependent. It can indicate work-life imbalance or a loss of the grounded comfort the card usually provides.","group": "minor","rank": "Queen","suit": "Pentacles","element": "Earth"},{"name": "King of Pentacles","tag": "King · Pentacles · Earth","keywords": ["prosperity","authority","business acumen","generosity","stability"],"meaning": "The King of Pentacles stands for worldly prosperity, business acumen, and outward authority over the material realm. Traditionally shown enthroned amid a flourishing vineyard or estate, holding a pentacle and scepter as symbols of hard-won wealth and command. Turning the suit's mastery outward, the card signals success built through discipline and practical skill, along with the generosity and steadiness to support others from a position of abundance. It favors sound financial judgment, reliable leadership, and enjoyment of comforts that have been earned.","reversed": "Reversed, the King of Pentacles suggests greed, materialism, or the misuse of financial or professional power. It can indicate poor financial judgment, stubbornness, or wealth pursued at the expense of other values.","group": "minor","rank": "King","suit": "Pentacles","element": "Earth"}];
